'use strict';

const app = document.getElementById('app');
const STORAGE_KEY = 'wss-growth-tools-v2';
const ROUTES = ['/resources/growth-dependency', '/resources/customer-segment', '/resources/positioning', '/resources/gtm-leak', '/resources/weekly-focus'];
const TOOL_ORDER = ['bottleneck','customer','positioning','leak','weekly'];
const TOOL_META = {
  bottleneck:{number:'01',title:'What is keeping growth dependent on you?',short:'Growth dependency',time:'4 minutes',desc:'Find the commercial capability that still relies most on founder knowledge, effort or judgement.',route:'/resources/growth-dependency'},
  customer:{number:'02',title:'Which customer segment should we prioritise next?',short:'Customer focus',time:'6 minutes',desc:'Compare real customer segments using evidence, economics and delivery fit, then choose where to focus.',route:'/resources/customer-segment'},
  positioning:{number:'03',title:'How do I explain what my product does?',short:'Positioning',time:'8 minutes',desc:'Turn customer evidence into one clear messaging direction that is ready to test.',route:'/resources/positioning'},
  leak:{number:'04',title:'Where are we losing customers?',short:'GTM leak',time:'5 minutes',desc:'Separate a volume problem, conversion leak and measurement gap, then identify the most important stage.',route:'/resources/gtm-leak'},
  weekly:{number:'05',title:'What should I focus on this week?',short:'Weekly focus',time:'5 minutes',desc:'Compare the strongest diagnoses, choose one constraint and leave with one evidence target and three actions.',route:'/resources/weekly-focus'}
};

const defaultState = () => ({profile:{product:'',customer:''},drafts:{},results:{},version:2});
let state = loadState();
let session = {};

function loadState(){
  try{
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return saved && saved.version === 2 ? saved : defaultState();
  }catch(e){return defaultState();}
}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function esc(value){return String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function clean(value){return String(value ?? '').trim().replace(/\s+/g,' ').replace(/[.!?]+$/,'');}
function lowerFirst(value){const x=clean(value);return x ? x[0].toLowerCase()+x.slice(1) : '';}
function sentence(value){const x=clean(value);return x ? x[0].toUpperCase()+x.slice(1)+'.' : '';}
function clampText(value,max=120){const x=clean(value);if(x.length<=max)return x;return x.slice(0,max).replace(/\s+\S*$/,'');}
function slug(value){return clean(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function uid(){return Math.random().toString(36).slice(2,9);}
function track(name,data={}){
  try{
    const event=String(name).trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
    window.dataLayer=window.dataLayer||[];
    window.dataLayer.push({event,tool_id:data.tool||currentTool()||'collection',tool_source:data.source||'',tool_result:data.result||'',tool_confidence:data.confidence||'',tool_stage:data.stage||'',tool_destination:data.destination||'',imported_results:Number(data.imported||0),page_path:location.pathname});
  }catch(e){}
}
function toast(text='Copied'){
  const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1500);
}
async function copyText(text){
  try{await navigator.clipboard.writeText(text);toast();track('Result Copied',{tool:currentTool()||'collection'});}catch(e){toast('Copy failed');}
}
function currentPath(){return ROUTES.includes(location.pathname)?location.pathname:ROUTES[0];}
function currentTool(){return Object.keys(TOOL_META).find(k=>TOOL_META[k].route===currentPath())||'bottleneck';}
function go(path,source='navigation'){
  const destination=ROUTES.includes(path)?path:'/resources#growth-tools';
  const destinationTool=Object.keys(TOOL_META).find(k=>TOOL_META[k].route===destination)||'';
  if(destinationTool)track('Next Tool Selected',{tool:currentTool(),source,destination:destinationTool});
  window.location.assign(destination);
}
document.addEventListener('click',e=>{
  const routeEl=e.target.closest('[data-route]');
  if(routeEl){e.preventDefault();go(routeEl.dataset.route,routeEl.dataset.source||'link');}
  const tracked=e.target.closest('[data-track]');
  if(tracked)track(tracked.dataset.track,{tool:tracked.dataset.tool||currentTool()||'collection'});
});

function layout(content){return `<div class="growth-tool-app">${content}</div>`;}
function completed(tool){return Boolean(state.results[tool]);}
function draftExists(tool){return Boolean(state.drafts[tool]);}
function statusHtml(tool){
  if(completed(tool))return '<span class="status done">Completed</span>';
  if(draftExists(tool))return '<span class="status progress">In progress</span>';
  return '<span class="chip">Not started</span>';
}
function buttonFor(tool){
  const label=completed(tool)?'Review result':draftExists(tool)?'Continue':'Start tool';
  return `<a class="btn ${completed(tool)?'secondary':'primary'}" href="${TOOL_META[tool].route}" data-route="${TOOL_META[tool].route}" data-source="collection">${label} →</a>`;
}
function home(){
  const done=TOOL_ORDER.filter(completed).length;
  const cards=TOOL_ORDER.map((tool,i)=>{
    const m=TOOL_META[tool];
    return `<article class="tool-card ${tool==='weekly'?'featured':''}"><div><span class="tool-number">${m.number}</span><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><div class="tool-meta"><span class="chip">${m.time}</span>${statusHtml(tool)}</div></div><div class="button-row">${buttonFor(tool)}</div></article>`;
  }).join('');
  const content=`<section class="hero shell"><div><span class="eyebrow">WSS Growth Tools</span><h2>Diagnose what is limiting growth, then choose the next move.</h2><p class="lead">Five focused tools for post-PMF B2B SaaS and AI companies. Use one for a specific decision, or move through the collection as a connected growth diagnosis.</p><div class="button-row"><a class="btn primary" href="/resources/growth-dependency" data-route="/resources/growth-dependency" data-source="hero">Start with the growth diagnosis →</a><a class="btn secondary" href="#tools">See all five tools</a></div><p class="micro">No account. No email gate. Answers and results are stored only in this browser.</p></div>
  <aside class="hero-card"><span class="section-label">Your collection</span><h3>${done} of 5 tools completed</h3><p>Each result can be used by the Weekly Focus Planner, so you do not have to repeat the diagnosis.</p><div class="flow-list">${TOOL_ORDER.map((t,i)=>`<div class="flow-item"><b>${i+1}</b><div><strong>${esc(TOOL_META[t].short)}</strong><span>${completed(t)?'Result ready':draftExists(t)?'Continue where you stopped':'Not started'}</span></div></div>`).join('')}</div></aside></section>
  <div class="ticker"><div class="ticker-track">Research → Experiment → Test → Scale → Research → Experiment → Test → Scale → Research → Experiment → Test → Scale → Research → Experiment → Test → Scale →</div></div>
  <section id="tools" class="section shell"><div class="section-head"><div><span class="section-label">The initial five</span><h2>One connected path from diagnosis to action.</h2></div><p>Tools 1 to 4 identify the strongest current signal. Tool 5 turns the selected diagnosis into a focused weekly plan.</p></div><div class="tools-grid">${cards}</div></section>`;
  return layout(content);
}

function introPage(tool,copy){
  return layout(`<section class="tool-intro shell"><a href="/resources#growth-tools" class="micro">← All growth tools</a><div style="margin-top:24px"><span class="eyebrow">${esc(copy.label)}</span><h2>${esc(copy.title)}</h2><p class="lead">${esc(copy.lead)}</p><div class="button-row"><button class="btn primary" onclick="${copy.startFn}()">${copy.startLabel||'Start the tool'} →</button>${copy.exampleFn?`<button class="btn secondary" onclick="${copy.exampleFn}()">Use a WSS example</button>`:''}</div><p class="micro">${esc(copy.meta)}</p></div><div class="tool-benefits">${copy.benefits.map(b=>`<div class="benefit"><strong>${esc(b[0])}</strong><span>${esc(b[1])}</span></div>`).join('')}</div></section>`,copy.title,copy.lead);
}
function progress(step,total,title){return `<div class="progress-meta"><strong>${esc(title)}</strong><span>Step ${step+1} of ${total}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round((step+1)/total*100)}%"></div></div>`;}
function optionButton(label,desc,index,selected,fn){return `<button type="button" class="option ${selected?'selected':''}" onclick="${fn}(${index})"><span class="option-mark">${String.fromCharCode(65+index)}</span><span><strong>${esc(label)}</strong><span class="desc">${esc(desc)}</span></span></button>`;}
function evidenceItems(items){return `<div class="evidence-list">${items.map((x,i)=>`<div class="evidence-item"><b>${i+1}</b><p>${esc(x)}</p></div>`).join('')}</div>`;}
function actionItems(items){return `<div class="action-list">${items.map((x,i)=>`<div class="action-item"><b>${i+1}</b><p>${esc(x)}</p></div>`).join('')}</div>`;}
function resultActions(copy,tool){return `<div class="result-actions"><button class="btn primary" onclick="copyText(${JSON.stringify(copy)})">Copy result</button><button class="btn secondary" onclick="window.print();track('PDF Selected',{tool:'${tool}'})">Print or save as PDF</button><button class="btn secondary" onclick="restartTool('${tool}')">Retake</button></div>`;}
function nextCard(title,text,route,label,sourceTool){return `<div class="next-card"><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div><a class="btn" href="${route}" data-route="${route}" data-source="${sourceTool}" onclick="track('Next Tool Selected',{tool:'${sourceTool}',destination:'${route}'})">${esc(label)} →</a></div>`;}
function restartTool(tool){delete state.drafts[tool];delete state.results[tool];saveState();session={};render();window.scrollTo(0,0);track('Tool Restarted',{tool});}


// 1. Founder dependency diagnostic
const bottlenecks=[
  {id:'sales',name:'Founder-held sales knowledge',title:'Transfer the founder sales narrative first',diagnosis:'Your strongest sales language, objection handling and commercial judgement still work best when you are personally involved. Growth is difficult to transfer without a drop in quality.',metric:'A capable team member can run a qualified discovery call and explain the value without founder preparation or rescue.',actions:['Review three recent sales calls and mark the moments that changed the prospect’s understanding.','Write a one-page founder sales narrative using the language, examples, objections and proof from those calls.','Have another person use it in a real or simulated conversation, then record where quality still drops.']},
  {id:'positioning',name:'Unclear positioning',title:'Make the customer and problem unmistakable',diagnosis:'The company is too difficult to recognise, remember or refer because the message is broad, inconsistent or product-led.',metric:'A best-fit buyer can accurately explain who the product is for and why it matters after seeing the opening message briefly.',actions:['Review the last ten wins and identify the repeated buyer, trigger, problem and consequence.','Write one specific message naming the customer, problem and outcome.','Test it with five target buyers and keep it only if they understand it without explanation.']},
  {id:'pipeline',name:'Inconsistent pipeline',title:'Build one pipeline process that runs every week',diagnosis:'New business arrives in bursts because it depends on referrals, founder energy or occasional campaigns rather than a protected weekly process.',metric:'Qualified opportunities continue at an agreed weekly rate without a founder-led burst of activity.',actions:['Trace the source of the last ten qualified opportunities.','Choose the single channel with the strongest evidence and define a weekly activity target.','Run it for four uninterrupted weeks, changing only one variable at a time.']},
  {id:'proof',name:'Weak customer proof',title:'Turn customer outcomes into proof that sells',diagnosis:'Customer evidence is too vague, hidden or generic to help a sceptical prospect decide without founder explanation.',metric:'A salesperson can send one relevant proof asset that answers the prospect’s main doubt without founder explanation.',actions:['Interview three successful customers about their before state, trigger and measurable change.','Create one case study using problem, action, result and timeframe.','Organise proof by customer type, problem and objection.']},
  {id:'learning',name:'No commercial learning rhythm',title:'Install a weekly commercial learning loop',diagnosis:'The team is active, but evidence is not consistently reviewed, documented and used to change the next decision.',metric:'Every week ends with a documented decision, named owner, evidence target and one learning carried into the next cycle.',actions:['Run a commercial retrospective covering what worked, failed and changed your understanding.','Schedule a weekly 45-minute commercial decision meeting with a fixed agenda.','Create a simple experiment ledger and define the next test before launching it.']},
  {id:'hiring',name:'Unclear hiring foundation',title:'Clarify the system before making the senior hire',diagnosis:'A senior growth or marketing hire may be expected to resolve customer, positioning, channel and ownership questions that are not yet explicit.',metric:'A strong candidate can understand the context, priorities, decision rights and 90-day success measures before accepting the role.',actions:['Write the real GTM brief, including customer, positioning, working channels and constraints.','Define what must be true after 30, 60 and 90 days.','Confirm whether the real need is leadership, a specialist or additional execution capacity.']}
];
const bottleneckQuestions=[
  {b:0,c:'Sales knowledge',q:'Could another person run your next three discovery calls as effectively as you?',h:'Think about the nuance, examples and objection handling that make prospects understand the value.',o:[['No, it still depends on me','They would miss important context or judgement.',3],['Mostly, with a careful briefing','They could do it, but only after founder preparation.',2],['Yes, without me','The narrative is documented and reliably used.',1]]},
  {b:0,c:'Sales knowledge',q:'Who gives the clearest answer when a prospect asks why customers choose you?',h:'Choose the answer that reflects a normal sales conversation.',o:[['The founder, every time','The strongest explanation still lives with one person.',3],['Usually the founder','Others can cover parts, but quality varies.',2],['The team answers consistently','The explanation has been transferred and trained.',1]]},
  {b:1,c:'Positioning',q:'Can the team describe who you help and the outcome you deliver in one consistent sentence?',h:'A useful answer identifies a recognisable customer, problem and outcome.',o:[['No, it changes by person or prospect','The message is flexible enough to become vague.',3],['There is a version, but it is not sharp','The basics exist, but specificity is weak.',2],['Yes, it is specific and consistent','The same clear message is used across the company.',1]]},
  {b:1,c:'Positioning',q:'How quickly would a best-fit buyer know your website is meant for them?',h:'Imagine a sceptical prospect scanning the opening section for five seconds.',o:[['They probably would not','The language is broad, generic or product-led.',3],['After reading carefully','The buyer has to work for the meaning.',2],['Immediately','The opening names their situation and desired outcome.',1]]},
  {b:2,c:'Pipeline',q:'How predictable is qualified new-business pipeline from month to month?',h:'Judge qualified conversations and opportunities, not raw lead volume.',o:[['Highly variable','Strong months are followed by worrying gaps.',3],['Somewhat consistent','There is activity, but forecasting is unreliable.',2],['Predictable','A repeatable process creates a steady flow.',1]]},
  {b:2,c:'Pipeline',q:'How much pipeline comes from a process that runs without the founder being personally active?',h:'Consider whether it continues during busy delivery periods or founder absence.',o:[['Almost none','It relies on founder relationships or bursts of effort.',3],['Some, but not enough','Parts run independently, but founder activity still matters.',2],['Most of it','The team runs a documented weekly process.',1]]},
  {b:3,c:'Customer proof',q:'How convincing is your evidence of customer outcomes to a sceptical buyer?',h:'Specific before-and-after evidence is stronger than broad praise.',o:[['Weak','Mostly broad claims, logos or vague testimonials.',3],['Moderate','Some useful evidence exists, but it is inconsistent.',2],['Strong','Specific results are used throughout the buying journey.',1]]},
  {b:3,c:'Customer proof',q:'What can the team send when a prospect asks for proof?',h:'The best proof matches the buyer’s situation and likely objection.',o:[['A deck and broad testimonials','The founder still has to explain why it matters.',3],['One or two case studies','Useful, but not always specific enough.',2],['A relevant proof pack','Evidence is easy to match and send.',1]]},
  {b:4,c:'Learning rhythm',q:'Does the team have a weekly session for pipeline, experiments, evidence and commercial decisions?',h:'A useful rhythm creates decisions rather than simply reporting activity.',o:[['No, it is ad hoc','Commercial learning is easy to lose or delay.',3],['Sometimes','It is irregular or mostly a status update.',2],['Yes, every week','It produces clear decisions, owners and next tests.',1]]},
  {b:4,c:'Learning rhythm',q:'How often does the team test messaging, review results and record what it learned?',h:'Look for a loop where evidence changes what the team does next.',o:[['Rarely','Insights stay in individual heads and activity repeats.',3],['Occasionally','Testing starts mainly when performance drops.',2],['Regularly','Learning improves the next cycle.',1]]},
  {b:5,c:'Hiring foundation',q:'Are you planning to hire a senior marketing or growth leader in the next six months?',h:'This includes an active search or a likely near-term decision.',o:[['Yes, actively','The success of the hire depends on the foundation being ready.',3],['Possibly','The decision is live but not final.',2],['No, not soon','This is not a current dependency.',1]]},
  {b:5,c:'Hiring foundation',q:'If that person started tomorrow, how clear would their first 90 days be?',h:'Consider the customer, positioning, channels, targets, constraints and decision rights.',o:[['Unclear','They would need to discover what the role is meant to solve.',3],['Partly clear','Important context and measures are missing.',2],['Very clear','The brief, priorities and evidence targets are ready.',1]]}
];
function bottleneckIntro(){return introPage('bottleneck',{label:'Founder dependency diagnostic',title:TOOL_META.bottleneck.title,lead:'Find the commercial capability that still works mainly because the founder is involved, then decide what evidence would prove it has been transferred.',startFn:'startBottleneck',startLabel:completed('bottleneck')?'Review or retake':'Start the diagnosis',meta:'About 4 minutes · 12 questions · No artificial overall percentage',benefits:[['Find one dependency','The result names the strongest current signal, not a generic maturity score.'],['See the evidence','The diagnosis uses the actual answers that caused it.'],['Move into action','The result becomes an input to the Weekly Focus Planner.']]});}
window.startBottleneck=function(){
  session.tool='bottleneck';session.step=0;session.answers=(state.drafts.bottleneck?.answers||Array(bottleneckQuestions.length).fill(null));track('Tool Started',{tool:'bottleneck'});renderBottleneckStep();
};
window.chooseBottleneck=function(i){session.answers[session.step]=i;state.drafts.bottleneck={answers:session.answers};saveState();renderBottleneckStep();};
window.bottleneckNext=function(){if(session.answers[session.step]===null)return;if(session.step<bottleneckQuestions.length-1){session.step++;renderBottleneckStep();window.scrollTo(0,0);}else finishBottleneck();};
window.bottleneckBack=function(){if(session.step===0){session={};render();}else{session.step--;renderBottleneckStep();window.scrollTo(0,0);}};
function renderBottleneckStep(){
  const q=bottleneckQuestions[session.step];
  app.innerHTML=layout(`<div class="wizard">${progress(session.step,bottleneckQuestions.length,q.c)}<section class="panel"><span class="step-kicker">${esc(q.c)}</span><h2>${esc(q.q)}</h2><p class="intro">${esc(q.h)}</p><div class="options">${q.o.map((o,i)=>optionButton(o[0],o[1],i,session.answers[session.step]===i,'chooseBottleneck')).join('')}</div><div class="wizard-actions"><button class="back" onclick="bottleneckBack()">← ${session.step===0?'Start':'Back'}</button><button class="btn primary" onclick="bottleneckNext()" ${session.answers[session.step]===null?'disabled':''}>${session.step===bottleneckQuestions.length-1?'See my result':'Continue'} →</button></div></section></div>`,TOOL_META.bottleneck.title,TOOL_META.bottleneck.desc);
}
function finishBottleneck(){
  const scores=Array(bottlenecks.length).fill(0);
  session.answers.forEach((a,i)=>scores[bottleneckQuestions[i].b]+=bottleneckQuestions[i].o[a][2]);
  const ranked=scores.map((score,i)=>({score,i})).sort((a,b)=>b.score-a.score);const top=ranked[0],second=ranked[1];const data=bottlenecks[top.i];
  const gap=top.score-second.score;const conf=gap>=2&&top.score>=5?'strong':gap>=1?'medium':'low';
  const evidence=bottleneckQuestions.map((q,i)=>({q,a:q.o[session.answers[i]],idx:i})).filter(x=>x.q.b===top.i).map(x=>`${x.q.q} You selected “${x.a[0]}”: ${x.a[1]}`);
  const levels=scores.map(s=>s>=5?'High dependency':s>=4?'Mixed': 'Transferred');
  const result={id:data.id,label:data.name,title:data.title,diagnosis:data.diagnosis,confidence:conf,evidence,evidenceTarget:data.metric,actions:data.actions,scores,levels,createdAt:new Date().toISOString()};
  state.results.bottleneck=result;delete state.drafts.bottleneck;saveState();track('Tool Completed',{tool:'bottleneck',result:data.id});session={};render();
}
function bottleneckResult(){
  const r=state.results.bottleneck;if(!r)return bottleneckIntro();
  const copy=`FOUNDER DEPENDENCY DIAGNOSIS\n\nFocus first: ${r.label}\nConfidence: ${r.confidence}\n\nDiagnosis\n${r.diagnosis}\n\nEvidence from the assessment\n${r.evidence.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nEvidence target\n${r.evidenceTarget}\n\nSuggested first moves\n${r.actions.map((x,i)=>`${i+1}. ${x}`).join('\n')}`;
  const stageRows=bottlenecks.map((b,i)=>{const level=r.levels[i];const cls=level==='High dependency'?'high':level==='Mixed'?'mixed':'good';return `<div class="stage-row"><strong>${esc(b.name)}</strong><div class="bar"></div><span class="level ${cls}">${level}</span></div>`;}).join('');
  const content=`<div class="results"><div class="result-head"><span class="eyebrow">Founder dependency diagnosis</span><h2>${esc(r.title)}</h2><p>${esc(r.diagnosis)}</p><span class="confidence ${r.confidence}">● ${r.confidence==='strong'?'Strong':r.confidence==='medium'?'Working':'Low'} confidence</span></div><div class="result-grid"><article class="result-card focus"><span class="section-label">Focus first</span><h2>${esc(r.label)}</h2><p>This is the strongest dependency signal in your answers. It is not a claim that every other area is healthy.</p></article><article class="result-card"><span class="section-label">Across the system</span><h3>Dependency levels, not a fake overall percentage</h3><div class="stage-list">${stageRows}</div></article><article class="result-card full"><span class="section-label">Why this showed up</span><h3>Your actual answers</h3>${evidenceItems(r.evidence)}</article><article class="result-card"><span class="section-label">Evidence target</span><h3>What would prove progress</h3><div class="copy-box">${esc(r.evidenceTarget)}</div></article><article class="result-card"><span class="section-label">Candidate first moves</span><h3>Take these into the weekly planner</h3>${actionItems(r.actions)}</article><article class="result-card warning full"><span class="section-label">What this does not prove</span><h3>Use it as a prioritisation hypothesis</h3><p>The result identifies the strongest dependency signal from your answers. Validate it with calls, operating data and team behaviour before making a major investment.</p></article></div>${resultActions(copy,'bottleneck')}${nextCard('Turn this diagnosis into one focused week','The Weekly Focus Planner will compare this result with any other completed tools and create one evidence target with three actions.','/resources/weekly-focus','Use this in the Weekly Focus Planner','bottleneck')}</div>`;
  return layout(content,TOOL_META.bottleneck.title,TOOL_META.bottleneck.desc);
}


// 2. Customer segment prioritisation
const customerCriteria=[
  {id:'urgency',title:'Problem urgency',q:'How urgently does each segment need the problem solved?',h:'Use recent behaviour, deadlines, consequences and willingness to act.',weight:1.2,labels:['Urgent now','Important, not urgent','Low urgency','Not sure']},
  {id:'evidence',title:'Direct evidence',q:'How much direct customer and revenue evidence do you have?',h:'Recent wins, paid pilots and repeated behaviour matter more than opinions.',weight:1.45,labels:['Repeated paid evidence','Some real evidence','Mostly assumptions','Not sure']},
  {id:'reach',title:'Reachability',q:'How easily can you identify and reach the right buyers?',h:'Consider list quality, existing access, communities, partners and channels.',weight:.9,labels:['Easy to identify and reach','Reachable with effort','Hard to reach','Not sure']},
  {id:'value',title:'Commercial value',q:'How valuable could a good customer in this segment be?',h:'Consider contract value, expansion potential and strategic value.',weight:1.15,labels:['High value','Moderate value','Low value','Not sure']},
  {id:'win',title:'Win rate and sales friction',q:'How likely are qualified opportunities in this segment to convert?',h:'Use actual sales cycles and objections where possible.',weight:1.05,labels:['Converts well','Mixed conversion','Hard to close','Not sure']},
  {id:'retention',title:'Retention and expansion',q:'How well do customers in this segment retain, use and expand?',h:'A segment that buys but does not stay is not a strong priority.',weight:1.25,labels:['Retains and expands','Mostly retains','Weak retention','Not sure']},
  {id:'fit',title:'Delivery fit',q:'How efficiently can your current team serve this segment?',h:'Consider onboarding, custom work, support burden and product fit.',weight:1,labels:['Strong delivery fit','Manageable','High delivery burden','Not sure']}
];
function customerIntro(){return introPage('customer',{label:'Customer segment prioritisation',title:TOOL_META.customer.title,lead:'Compare two or three real segments using evidence, economics, retention and delivery fit. The result recommends a focus while making uncertainty visible.',startFn:'startCustomer',startLabel:completed('customer')?'Review or retake':'Compare my segments',meta:'About 6 minutes · Post-PMF decision logic · No false 91/100 precision',benefits:[['Use real segments','Compare groups you could actually build a list for.'],['Weight evidence properly','Paid behaviour and retention matter more than enthusiasm.'],['Choose and exclude','Leave with a leading segment and a group to deprioritise.']]});}
window.startCustomer=function(){
  const d=state.drafts.customer||{};session={tool:'customer',step:d.step||0,names:d.names||['',''],ratings:d.ratings||customerCriteria.map(()=>[])};track('Tool Started',{tool:'customer'});renderCustomer();
};
window.setSegmentCount=function(count){
  session.names=session.names.slice(0,count);while(session.names.length<count)session.names.push('');persistCustomer();renderCustomer();
};
window.updateSegmentName=function(i,value){session.names[i]=value;persistCustomer();const btn=document.getElementById('segmentContinue');if(btn)btn.disabled=!validSegments();};
function validSegments(){const names=session.names.map(clean);return names.length>=2&&names.every(n=>n.split(' ').length>=3)&&new Set(names.map(n=>n.toLowerCase())).size===names.length;}
function persistCustomer(){state.drafts.customer={step:session.step,names:session.names,ratings:session.ratings};saveState();}
window.customerNamesNext=function(){if(!validSegments())return;session.names=session.names.map(clean);session.step=1;persistCustomer();renderCustomer();window.scrollTo(0,0);};
window.chooseCustomerRating=function(segIndex,value){const ci=session.step-1;if(!session.ratings[ci])session.ratings[ci]=[];session.ratings[ci][segIndex]=value;persistCustomer();renderCustomer();};
window.customerNext=function(){const ci=session.step-1;if(session.ratings[ci]?.length!==session.names.length||session.ratings[ci].some(v=>v===undefined))return;if(session.step<customerCriteria.length){session.step++;persistCustomer();renderCustomer();window.scrollTo(0,0);}else finishCustomer();};
window.customerBack=function(){if(session.step===0){session={};render();}else{session.step--;persistCustomer();renderCustomer();window.scrollTo(0,0);}};
function renderCustomer(){
  if(session.step===0){
    app.innerHTML=layout(`<div class="wizard">${progress(0,customerCriteria.length+1,'Define the segments')}<section class="panel"><span class="step-kicker">Customer options</span><h2>Which segments are you genuinely considering?</h2><p class="intro">Use a specific role or company type, stage and relevant situation. Compare two by default, or add a third when it is a real decision.</p><div class="button-row"><button class="btn ${session.names.length===2?'primary':'secondary'}" onclick="setSegmentCount(2)">Compare 2</button><button class="btn ${session.names.length===3?'primary':'secondary'}" onclick="setSegmentCount(3)">Compare 3</button></div><div class="segment-list">${session.names.map((n,i)=>`<div class="field"><label>Segment ${i+1}</label><input value="${esc(n)}" oninput="updateSegmentName(${i},this.value)" placeholder="e.g. Post-PMF B2B SaaS founders with inconsistent pipeline"><div class="hint">Role or company type + stage + relevant situation.</div></div>`).join('')}</div><div class="quality ${validSegments()?'good':'warn'}">${validSegments()?'These segments are specific enough to compare.':'Each segment needs at least three words and must be meaningfully different.'}</div><div class="wizard-actions"><button class="back" onclick="customerBack()">← Start</button><button id="segmentContinue" class="btn primary" onclick="customerNamesNext()" ${validSegments()?'':'disabled'}>Start comparison →</button></div></section></div>`,TOOL_META.customer.title,TOOL_META.customer.desc);return;
  }
  const ci=session.step-1,c=customerCriteria[ci];const complete=session.ratings[ci]?.length===session.names.length&&!session.ratings[ci].some(v=>v===undefined);
  const rows=session.names.map((n,si)=>`<div class="segment-row"><strong>${esc(n)}</strong><div class="rating-buttons">${c.labels.map((label,i)=>{const value=i===3?null:3-i;const selected=session.ratings[ci]?.[si]===value;return `<button class="rating ${selected?'selected':''}" onclick="chooseCustomerRating(${si},${value===null?'null':value})">${esc(label)}</button>`;}).join('')}</div></div>`).join('');
  app.innerHTML=layout(`<div class="wizard">${progress(session.step,customerCriteria.length+1,c.title)}<section class="panel"><span class="step-kicker">${esc(c.title)}</span><h2>${esc(c.q)}</h2><p class="intro">${esc(c.h)}</p><div class="segment-list">${rows}</div><div class="wizard-actions"><button class="back" onclick="customerBack()">← Back</button><button class="btn primary" onclick="customerNext()" ${complete?'':'disabled'}>${session.step===customerCriteria.length?'See recommendation':'Continue'} →</button></div></section></div>`,TOOL_META.customer.title,TOOL_META.customer.desc);
}
function finishCustomer(){
  const totals=session.names.map(()=>0),known=session.names.map(()=>0),strengths=session.names.map(()=>[]),gaps=session.names.map(()=>[]);
  customerCriteria.forEach((c,ci)=>session.names.forEach((n,si)=>{const v=session.ratings[ci][si];if(v===null){gaps[si].push(c.title);totals[si]+=1*c.weight;}else{totals[si]+=v*c.weight;known[si]++;if(v===3)strengths[si].push(c.title);if(v<=1)gaps[si].push(c.title);}}));
  const ranked=totals.map((score,i)=>({score,i})).sort((a,b)=>b.score-a.score);const top=ranked[0],second=ranked[1];const max=customerCriteria.reduce((s,c)=>s+3*c.weight,0);const gap=(top.score-second.score)/max;const knownRate=known[top.i]/customerCriteria.length;
  const conf=knownRate<.65?'low':gap>.12?'strong':gap>.05?'medium':'low';
  const winner=session.names[top.i],runner=session.names[second.i],deprioritise=session.names[ranked[ranked.length-1].i];
  const weakest=gaps[top.i][0]||'Direct customer evidence';
  const result={winner,runner,deprioritise,confidence:conf,ranked:ranked.map((r,idx)=>({name:session.names[r.i],label:idx===0?'Leading option':idx===1?'Close alternative':'Deprioritise',known:known[r.i],strengths:strengths[r.i],gaps:gaps[r.i]})),evidenceTarget:`Collect one piece of behavioural or revenue evidence that resolves the weakest area for ${winner}: ${weakest}.`,actions:[`Review the last ten wins, losses and active opportunities involving ${winner}.`,`Speak with three recent buyers or customers in ${winner} about the trigger, alternatives and decision criteria.`,`Run one real offer or pipeline test aimed only at ${winner}, then compare qualified response and conversion.`],createdAt:new Date().toISOString()};
  state.results.customer=result;state.profile.customer=winner;delete state.drafts.customer;saveState();track('Tool Completed',{tool:'customer',confidence:conf});session={};render();
}
function customerResult(){
  const r=state.results.customer;if(!r)return customerIntro();
  const copy=`CUSTOMER SEGMENT PRIORITY\n\nLeading option: ${r.winner}\nConfidence: ${r.confidence}\nClose alternative: ${r.runner}\nDeprioritise for now: ${r.deprioritise}\n\nEvidence target\n${r.evidenceTarget}\n\nCandidate validation moves\n${r.actions.map((x,i)=>`${i+1}. ${x}`).join('\n')}`;
  const ranks=r.ranked.map((x,i)=>`<div class="rank-card ${i===0?'top':''}"><h4>${esc(x.name)}</h4><div class="rank-meta"><span class="status ${i===0?'done':'progress'}">${esc(x.label)}</span><span class="chip">${x.known} of ${customerCriteria.length} criteria known</span></div>${x.strengths.length?`<p><strong>Strongest:</strong> ${esc(x.strengths.slice(0,2).join(', '))}</p>`:''}${x.gaps.length?`<p><strong>Needs evidence:</strong> ${esc(x.gaps.slice(0,2).join(', '))}</p>`:''}</div>`).join('');
  const content=`<div class="results"><div class="result-head"><span class="eyebrow">Customer segment priority</span><h2>Prioritise ${esc(r.winner)}.</h2><p>This is the leading option based on the evidence, economics and delivery fit you entered. It is a decision hypothesis, not a permanent ICP definition.</p><span class="confidence ${r.confidence}">● ${r.confidence==='strong'?'Strong':r.confidence==='medium'?'Working':'Low'} confidence</span></div><div class="result-grid"><article class="result-card focus"><span class="section-label">Leading option</span><h2>${esc(r.winner)}</h2><p>Use this as the primary segment for the next controlled messaging, pipeline or offer test.</p></article><article class="result-card"><span class="section-label">Explicit exclusion</span><h3>Deprioritise for now</h3><div class="copy-box">${esc(r.deprioritise)}</div><p>Deprioritising is temporary. Reopen the decision when new evidence changes the economics or fit.</p></article><article class="result-card full"><span class="section-label">Ranked comparison</span><h3>Relative position, without fake precision</h3>${ranks}</article><article class="result-card"><span class="section-label">Evidence target</span><h3>Resolve the weakest assumption</h3><div class="copy-box">${esc(r.evidenceTarget)}</div></article><article class="result-card"><span class="section-label">Candidate validation moves</span><h3>Take these into the weekly planner</h3>${actionItems(r.actions)}</article><article class="result-card warning full"><span class="section-label">What this does not prove</span><h3>A leading segment can still fail in market</h3><p>The result does not prove market size, willingness to pay or repeatable acquisition. It prioritises where to collect the next evidence.</p></article></div>${resultActions(copy,'customer')}${nextCard('Turn the chosen segment into clear messaging','The Positioning Builder is already prefilled with your leading customer segment.','/resources/positioning','Build the message','customer')}</div>`;
  return layout(content,TOOL_META.customer.title,TOOL_META.customer.desc);
}


// 3. Positioning builder
const positioningFields=[
  {key:'product',title:'Name the product',q:'What is the product or service called?',hint:'Use the name a customer would recognise.',placeholder:'Crux',min:2,example:'Crux'},
  {key:'customer',title:'Choose the customer',q:'Who exactly is this message for?',hint:'Use a plural customer group, with role or company type, stage and situation.',placeholder:'Post-PMF B2B SaaS founders with inconsistent pipeline',min:5,example:'Post-PMF B2B SaaS and AI founders with inconsistent pipeline'},
  {key:'trigger',title:'Name the trigger',q:'What is happening when they start looking for help?',hint:'Write a clause without “when”, for example: pipeline becomes unpredictable despite more activity.',placeholder:'pipeline becomes unpredictable despite more activity',min:6,example:'pipeline becomes unpredictable even though the team is running more campaigns'},
  {key:'problem',title:'Name the problem',q:'What problem are they facing?',hint:'Use a noun phrase, for example: difficulty identifying the real commercial constraint.',placeholder:'difficulty identifying the real commercial constraint',min:5,example:'difficulty identifying the real commercial constraint holding back pipeline'},
  {key:'consequence',title:'Show the cost',q:'What happens if the problem remains unsolved?',hint:'Write a complete sentence about revenue, cost, risk, delay or founder dependency.',placeholder:'They waste budget and team time on disconnected activity.',min:7,example:'They waste budget and team time on disconnected activity while the founder remains the decision bottleneck.'},
  {key:'outcome',title:'Define the outcome',q:'What should the customer be able to do?',hint:'Start with an action verb. This becomes the headline, for example: Build a predictable pipeline without founder heroics.',placeholder:'Build a predictable pipeline without founder heroics',min:5,example:'Find the real constraint and build a repeatable growth rhythm'},
  {key:'alternative',title:'Name the alternative',q:'What do they use or do instead today?',hint:'Use a noun phrase, for example: founder intuition, broad agency retainers or disconnected campaigns.',placeholder:'founder intuition and disconnected campaigns',min:4,example:'founder intuition, broad strategy decks and disconnected campaigns'},
  {key:'mechanism',title:'Explain the difference',q:'How does your approach create the outcome?',hint:'Start with an “-ing” word, “using” or “combining”, for example: diagnosing the constraint before recommending activity.',placeholder:'diagnosing the constraint before recommending activity',min:5,example:'diagnosing the constraint first, running controlled tests and transferring the system into the team'},
  {key:'proof',title:'Add evidence',q:'What evidence supports the direction?',hint:'Metrics, case studies and repeated customer behaviour are stronger than general praise. This can be left blank.',placeholder:'£18M+ revenue influenced and repeated founder evidence across 479+ sessions',min:0,example:'£18M+ revenue influenced, £6M+ acquisition spend managed and repeated founder evidence across 479+ sessions'}
];
const vagueWords=['innovative','seamless','revolutionary','best-in-class','world-class','empower','unlock','transform','all-in-one','cutting-edge','ai-powered','powerful solution'];
function positioningIntro(){return introPage('positioning',{label:'Positioning and messaging builder',title:TOOL_META.positioning.title,lead:'Make the positioning choices first, then generate four focused outputs with a visible quality check and editable copy.',startFn:'startPositioning',exampleFn:'examplePositioning',startLabel:completed('positioning')?'Review or retake':'Build my messaging',meta:'About 8 minutes · Four useful outputs · Editable before copying',benefits:[['One strategic direction','No ten-variant AI copy dump.'],['Grammar-safe inputs','Each question asks for a phrase that fits the final structure.'],['Visible quality check','Generic wording, weak evidence and excessive length are flagged.']]});}
window.startPositioning=function(){
  const prefill={product:state.profile.product||'',customer:state.profile.customer||''};const saved=state.drafts.positioning?.answers||{};session={tool:'positioning',step:0,answers:{...prefill,...saved}};track('Tool Started',{tool:'positioning'});renderPositioning();
};
window.examplePositioning=function(){session={tool:'positioning',step:0,answers:Object.fromEntries(positioningFields.map(f=>[f.key,f.example]))};state.drafts.positioning={answers:session.answers};saveState();track('Tool Started',{tool:'positioning',source:'example'});renderPositioning();};
function positioningQuality(field,value){
  const v=clean(value);if(!v&&field.min===0)return{ok:true,kind:'warn',text:'Optional. Leaving this blank will make the claims a lower-confidence hypothesis.'};
  if(v.length<field.min)return{ok:false,kind:'bad',text:'Add a little more detail so the output can be specific.'};
  const vague=vagueWords.find(w=>v.toLowerCase().includes(w));if(vague)return{ok:false,kind:'bad',text:`“${vague}” is difficult to picture. Replace it with what changes in practice.`};
  if(field.key==='customer'&&v.split(' ').length<4)return{ok:false,kind:'bad',text:'Add a role or company type, stage and relevant situation.'};
  if(field.key==='trigger'&&/^when\b/i.test(v))return{ok:false,kind:'bad',text:'Remove “when”. The final copy adds it for you.'};
  if(field.key==='problem'&&/^(they|we|it)\b/i.test(v))return{ok:false,kind:'bad',text:'Use a noun phrase rather than a full sentence, for example: difficulty identifying the real constraint.'};
  if(field.key==='outcome'&&/^(to|we|they|customers?)\b/i.test(v))return{ok:false,kind:'bad',text:'Start with an action verb, for example: Build, Find, Reduce or Create.'};
  if(field.key==='mechanism'&&!/^(using|combining|diagnosing|identifying|analysing|analyzing|testing|connecting|mapping|reviewing|building|turning|capturing|automating|prioritising|prioritizing|measuring|matching|integrating|creating|providing|replacing|transferring|running)\b/i.test(v))return{ok:false,kind:'warn',text:'Start with an “-ing” action so the final sentence reads naturally.'};
  if(v.split(' ').length>28)return{ok:false,kind:'warn',text:'Shorten this to one idea. Long inputs create weak messaging.'};
  return{ok:true,kind:'good',text:'Specific enough to use in the working direction.'};
}
window.updatePositioning=function(value){const f=positioningFields[session.step];session.answers[f.key]=value;state.drafts.positioning={answers:session.answers};saveState();const q=positioningQuality(f,value);const el=document.getElementById('positionQuality');if(el){el.className=`quality ${q.kind}`;el.textContent=q.text;}const btn=document.getElementById('positionNext');if(btn)btn.disabled=!q.ok;};
window.positionNext=function(){const f=positioningFields[session.step],q=positioningQuality(f,session.answers[f.key]||'');if(!q.ok)return;session.answers[f.key]=clean(session.answers[f.key]);if(session.step<positioningFields.length-1){session.step++;renderPositioning();window.scrollTo(0,0);}else renderPositionReview();};
window.positionBack=function(){if(session.step===0){session={};render();}else{session.step--;renderPositioning();window.scrollTo(0,0);}};
function renderPositioning(){
  const f=positioningFields[session.step],v=session.answers[f.key]||'',q=positioningQuality(f,v);
  app.innerHTML=layout(`<div class="wizard">${progress(session.step,positioningFields.length,f.title)}<section class="panel"><span class="step-kicker">${esc(f.title)}</span><h2>${esc(f.q)}</h2><p class="intro">${esc(f.hint)}</p><div class="field"><label>Your answer</label><textarea autofocus oninput="updatePositioning(this.value)" placeholder="${esc(f.placeholder)}">${esc(v)}</textarea><div id="positionQuality" class="quality ${q.kind}">${esc(q.text)}</div></div><details style="margin-top:14px"><summary class="micro">See a useful example</summary><p>${esc(f.example)}</p></details><div class="wizard-actions"><button class="back" onclick="positionBack()">← ${session.step===0?'Start':'Back'}</button><button id="positionNext" class="btn primary" onclick="positionNext()" ${q.ok?'':'disabled'}>${session.step===positioningFields.length-1?'Review direction':'Continue'} →</button></div></section></div>`,TOOL_META.positioning.title,TOOL_META.positioning.desc);
}
function renderPositionReview(){
  app.innerHTML=layout(`<div class="wizard">${progress(positioningFields.length-1,positioningFields.length,'Review the choices')}<section class="panel"><span class="step-kicker">Before the copy</span><h2>Is this the direction you want to test?</h2><p class="intro">The output will only be as strong as these strategic choices.</p><div class="review-list">${positioningFields.map(f=>`<div class="review-row"><span>${esc(f.title)}</span><strong>${esc(session.answers[f.key]||'Not provided')}</strong></div>`).join('')}</div><div class="wizard-actions"><button class="back" onclick="session.step=${positioningFields.length-1};renderPositioning()">← Edit</button><button class="btn primary" onclick="finishPositioning()">Generate messaging →</button></div></section></div>`,TOOL_META.positioning.title,TOOL_META.positioning.desc);
}
window.finishPositioning=function(){
  const a=Object.fromEntries(Object.entries(session.answers).map(([k,v])=>[k,clean(v)]));
  const headline=sentence(a.outcome);
  const subheadline=`${a.product} helps ${a.customer} ${lowerFirst(a.outcome)} by ${lowerFirst(a.mechanism)}.`;
  const oneLine=subheadline;
  const problemStatement=`When ${lowerFirst(a.trigger)}, ${a.customer} face ${lowerFirst(a.problem)}. ${sentence(a.consequence)}`;
  const salesIntro=`We work with ${a.customer} when ${lowerFirst(a.trigger)}. ${a.product} helps them ${lowerFirst(a.outcome)} by ${lowerFirst(a.mechanism)}.`;
  const outreach=`I noticed ${lowerFirst(a.trigger)} is a common issue for ${a.customer}. We help teams ${lowerFirst(a.outcome)}. Open to comparing notes?`;
  const differentiation=`Instead of ${lowerFirst(a.alternative)}, ${a.product} works by ${lowerFirst(a.mechanism)}.`;
  const issues=[];
  if(headline.length>80)issues.push('The headline is long. Aim for fewer than 80 characters.');
  if(subheadline.length>220)issues.push('The subheadline is long. Remove one idea before publishing.');
  if(!a.proof)issues.push('No proof was supplied. Treat the outcome and differentiation as hypotheses.');
  if(vagueWords.some(w=>(headline+' '+subheadline).toLowerCase().includes(w)))issues.push('Generic language remains in the output. Replace it with an observable result.');
  const conf=a.proof&&/[0-9£$%+]/.test(a.proof)?'strong':a.proof?'medium':'low';
  const result={...a,headline,subheadline,oneLine,problemStatement,salesIntro,outreach,differentiation,issues,confidence:conf,evidenceTarget:`Show the headline and subheadline to five people in ${a.customer}. Keep the direction only if they can explain what ${a.product} does, who it is for and why it matters without additional explanation.`,actions:[`Show the hero message to five target customers without explaining it.`,`Record the exact words they use to describe the problem and outcome.`,`Test the outreach opener with 20 carefully selected prospects and compare qualified responses.`],createdAt:new Date().toISOString()};
  state.results.positioning=result;state.profile.product=a.product;state.profile.customer=a.customer;delete state.drafts.positioning;saveState();track('Tool Completed',{tool:'positioning',confidence:conf});session={};render();
};
window.editOutput=function(key,value){state.results.positioning[key]=value;saveState();};
function outputBlock(label,key,value){return `<article class="result-card"><span class="section-label">${esc(label)}</span><div class="output-row"><textarea class="editable-output" oninput="editOutput('${key}',this.value)">${esc(value)}</textarea><button class="copy-small" onclick="copyText(state.results.positioning['${key}'])">Copy</button></div></article>`;}
function positioningResult(){
  const r=state.results.positioning;if(!r)return positioningIntro();
  const copy=`WORKING POSITIONING DIRECTION\n\nHOMEPAGE HEADLINE\n${r.headline}\n\nHOMEPAGE SUBHEADLINE\n${r.subheadline}\n\nSALES INTRODUCTION\n${r.salesIntro}\n\nOUTREACH OPENER\n${r.outreach}\n\nPROBLEM STATEMENT\n${r.problemStatement}\n\nDIFFERENTIATION\n${r.differentiation}\n\nEVIDENCE\n${r.proof||'No evidence supplied'}\n\nCUSTOMER TEST\n${r.evidenceTarget}`;
  const content=`<div class="results"><div class="result-head"><span class="eyebrow">Working messaging direction</span><h2>${esc(r.headline)}</h2><p>These are editable working drafts. Test whether customers understand them before publishing or scaling.</p><span class="confidence ${r.confidence}">● ${r.confidence==='strong'?'Stronger evidence':r.confidence==='medium'?'Working hypothesis':'Low evidence'}</span></div><div class="result-grid"><article class="result-card focus full"><span class="section-label">Positioning foundation</span><div class="summary-grid"><div class="summary-card"><span>For</span><strong>${esc(r.customer)}</strong></div><div class="summary-card"><span>Outcome</span><strong>${esc(r.outcome)}</strong></div><div class="summary-card"><span>Mechanism</span><strong>${esc(r.mechanism)}</strong></div></div></article>${outputBlock('Homepage headline','headline',r.headline)}${outputBlock('Homepage subheadline','subheadline',r.subheadline)}${outputBlock('Sales introduction','salesIntro',r.salesIntro)}${outputBlock('Outreach opener','outreach',r.outreach)}<article class="result-card"><span class="section-label">Problem statement</span><div class="copy-box">${esc(r.problemStatement)}</div><button class="copy-small" style="margin-top:8px" onclick="copyText(state.results.positioning.problemStatement)">Copy</button></article><article class="result-card"><span class="section-label">Differentiation</span><div class="copy-box">${esc(r.differentiation)}</div><button class="copy-small" style="margin-top:8px" onclick="copyText(state.results.positioning.differentiation)">Copy</button></article><article class="result-card ${r.issues.length?'warning':''} full"><span class="section-label">Quality check</span><h3>${r.issues.length?'Resolve these before publishing':'The draft passes the current structural checks'}</h3>${r.issues.length?evidenceItems(r.issues):'<p>The inputs are specific, the sentence structures are complete and the main claims are supported by evidence. Customer testing is still required.</p>'}</article><article class="result-card"><span class="section-label">Evidence behind it</span><h3>${r.proof?'Proof supplied':'No proof supplied'}</h3><p>${esc(r.proof||'Keep the outcome and differentiation framed as hypotheses until you have customer behaviour or results to support them.')}</p></article><article class="result-card"><span class="section-label">Customer test</span><h3>Validate understanding, not applause</h3><div class="copy-box">${esc(r.evidenceTarget)}</div></article></div>${resultActions(copy,'positioning')}${nextCard('Find where the customer journey is leaking','Use the GTM Leak Diagnostic to see whether the message, pipeline, conversion, activation or retention is the most important constraint.','/resources/gtm-leak','Diagnose the customer journey','positioning')}</div>`;
  return layout(content,TOOL_META.positioning.title,TOOL_META.positioning.desc);
}


// 4. GTM leak diagnostic
const leakStages=[
  {id:'demand',name:'Right-fit demand',desc:'Enough best-fit prospects enter the journey.',metric:'Qualified conversations created per week',actions:{measurement:['Define exactly what counts as a right-fit prospect and qualified conversation.','Instrument the source and qualification status for every new conversation.','Review the last 20 inbound and outbound responses to establish a baseline.'],volume:['Choose the one channel with the strongest evidence and define a protected weekly activity target.','Run one focused message and audience combination for two full weeks.','Review qualified conversations, not impressions or raw leads.'],conversion:['Review 10 recent responses and non-responses to identify message or audience mismatch.','Write one hypothesis about the signal, customer or problem language.','Test one controlled change with a clear response threshold.']}},
  {id:'qualification',name:'Qualification',desc:'The right prospects become real opportunities.',metric:'Qualified opportunity rate',actions:{measurement:['Define the minimum criteria for a qualified opportunity.','Tag the last 20 conversations against those criteria.','Agree one owner and one weekly qualification review.'],volume:['Audit whether the audience and channels produce enough right-fit conversations.','Tighten the customer definition and list criteria.','Run one targeted acquisition test before changing sales process.'],conversion:['Review the last 10 disqualified or stalled conversations.','Identify the most common mismatch in problem, timing, authority or budget.','Change one qualification question or pre-call signal, then compare the next 10.']}},
  {id:'sales',name:'Sales conversion',desc:'Qualified opportunities become paying customers.',metric:'Qualified opportunity to closed-won rate',actions:{measurement:['Define each sales stage and the evidence required to enter it.','Rebuild the last 15 opportunities using the same stage definitions.','Start a weekly loss and stall review.'],volume:['Confirm there are enough qualified opportunities before changing the sales process.','Set a minimum weekly opportunity target.','Protect prospecting capacity while reviewing conversion.'],conversion:['Review five wins, five losses and five stalled deals.','Identify the repeated objection, missing proof or decision friction.','Change one part of the sales narrative or follow-up and test it on the next five opportunities.']}},
  {id:'activation',name:'Activation',desc:'New customers reach meaningful value quickly.',metric:'Time to first meaningful value',actions:{measurement:['Define the first customer behaviour that predicts successful use.','Measure time from purchase to that behaviour for the last 20 customers.','Create a weekly list of customers who have not activated.'],volume:['Confirm enough new customers are entering onboarding to make the signal reliable.','Review onboarding capacity and ownership.','Use qualitative onboarding evidence until the sample is larger.'],conversion:['Interview five customers who activated and five who did not.','Identify the single step where momentum drops.','Remove, simplify or support that step, then compare the next cohort.']}},
  {id:'retention',name:'Retention',desc:'Customers continue receiving value and stay.',metric:'Logo and revenue retention by segment',actions:{measurement:['Choose one retention window and calculate it consistently by customer segment.','Review every churned account from the last six months.','Add a simple customer-risk review with named owners.'],volume:['Confirm the cohort is large enough for meaningful quantitative retention analysis.','Use customer interviews and product behaviour to identify early patterns.','Avoid broad conclusions from a very small sample.'],conversion:['Review churn reasons, usage and support patterns for the last 10 losses.','Identify the earliest observable warning signal.','Run one proactive retention intervention for every account showing that signal.']}},
  {id:'expansion',name:'Expansion and advocacy',desc:'Successful customers grow, renew and refer.',metric:'Expansion revenue and qualified referrals',actions:{measurement:['Define expansion and advocacy events you can record consistently.','Review the last 20 successful customers for missed opportunities.','Add a quarterly customer outcome and expansion review.'],volume:['Confirm enough customers have reached clear value before pushing expansion.','Build a list of customers with proven outcomes.','Focus first on creating success signals, then ask for expansion or advocacy.'],conversion:['Interview successful customers who did and did not expand.','Identify the outcome, trigger and stakeholder that created expansion.','Test one outcome review and relevant next offer with five strong accounts.']}}
];
const leakStatus=[{id:'unknown',label:'Not measured',desc:'We cannot reliably see what happens at this stage.',severity:2.4},{id:'volume',label:'Insufficient volume',desc:'Too few right-fit people or customers reach this stage.',severity:2.6},{id:'conversion',label:'Converting poorly',desc:'Enough reach the stage, but too few progress.',severity:3},{id:'healthy',label:'Mostly healthy',desc:'Performance is understood and broadly acceptable.',severity:.5}];
const impacts=[{id:'high',label:'High commercial impact',mult:1.4},{id:'medium',label:'Moderate impact',mult:1},{id:'low',label:'Lower impact',mult:.6}];
function leakIntro(){return introPage('leak',{label:'GTM leak diagnostic',title:TOOL_META.leak.title,lead:'Separate volume, conversion and measurement problems across six stages, then identify the stage with the greatest likely commercial impact.',startFn:'startLeak',startLabel:completed('leak')?'Review or retake':'Diagnose the journey',meta:'About 5 minutes · 6 stages · Missing measurement is treated as its own constraint',benefits:[['Name the failure type','Do not confuse low volume with poor conversion.'],['Weight commercial impact','The weakest-looking stage is not always the most important.'],['Choose one evidence target','The result moves directly into the Weekly Focus Planner.']]});}
window.startLeak=function(){const d=state.drafts.leak||{};session={tool:'leak',step:d.step||0,answers:d.answers||leakStages.map(()=>({status:null,impact:null}))};track('Tool Started',{tool:'leak'});renderLeak();};
function persistLeak(){state.drafts.leak={step:session.step,answers:session.answers};saveState();}
window.chooseLeakStatus=function(id){session.answers[session.step].status=id;persistLeak();renderLeak();};
window.chooseLeakImpact=function(id){session.answers[session.step].impact=id;persistLeak();renderLeak();};
window.leakNext=function(){const a=session.answers[session.step];if(!a.status||!a.impact)return;if(session.step<leakStages.length-1){session.step++;persistLeak();renderLeak();window.scrollTo(0,0);}else finishLeak();};
window.leakBack=function(){if(session.step===0){session={};render();}else{session.step--;persistLeak();renderLeak();window.scrollTo(0,0);}};
function renderLeak(){
  const s=leakStages[session.step],a=session.answers[session.step];
  app.innerHTML=layout(`<div class="wizard">${progress(session.step,leakStages.length,s.name)}<section class="panel"><span class="step-kicker">${esc(s.name)}</span><h2>What is happening at this stage?</h2><p class="intro">${esc(s.desc)}</p><div class="options">${leakStatus.map((o,i)=>`<button type="button" class="option ${a.status===o.id?'selected':''}" onclick="chooseLeakStatus('${o.id}')"><span class="option-mark">${String.fromCharCode(65+i)}</span><span><strong>${esc(o.label)}</strong><span class="desc">${esc(o.desc)}</span></span></button>`).join('')}</div><h3 style="margin-top:28px">How commercially important is this stage right now?</h3><div class="rating-buttons">${impacts.map(i=>`<button class="rating ${a.impact===i.id?'selected':''}" onclick="chooseLeakImpact('${i.id}')">${esc(i.label)}</button>`).join('')}</div><div class="wizard-actions"><button class="back" onclick="leakBack()">← ${session.step===0?'Start':'Back'}</button><button class="btn primary" onclick="leakNext()" ${a.status&&a.impact?'':'disabled'}>${session.step===leakStages.length-1?'See diagnosis':'Continue'} →</button></div></section></div>`,TOOL_META.leak.title,TOOL_META.leak.desc);
}
function finishLeak(){
  const scored=session.answers.map((a,i)=>{const status=leakStatus.find(x=>x.id===a.status),impact=impacts.find(x=>x.id===a.impact);return{score:status.severity*impact.mult,i,status,impact};}).sort((a,b)=>b.score-a.score);
  const top=scored[0],second=scored[1],stage=leakStages[top.i];const gap=top.score-second.score;const unknowns=session.answers.filter(a=>a.status==='unknown').length;
  const conf=unknowns>=3?'low':gap>=.8?'strong':gap>=.3?'medium':'low';
  const type=top.status.id==='unknown'?'Measurement gap':top.status.id==='volume'?'Volume constraint':top.status.id==='conversion'?'Conversion leak':'Lowest-priority healthy stage';
  const evidenceTarget=top.status.id==='unknown'?`Establish a reliable baseline for ${stage.metric.toLowerCase()} and review it by customer segment.`:top.status.id==='volume'?`Create enough right-fit volume at ${stage.name.toLowerCase()} to judge performance using ${stage.metric.toLowerCase()}.`:`Improve ${stage.metric.toLowerCase()} through one controlled change, with the current baseline recorded before the test.`;
  const actions=stage.actions[top.status.id==='healthy'?'measurement':top.status.id];
  const result={stageId:stage.id,stage:stage.name,type,status:top.status.id,impact:top.impact.id,confidence:conf,diagnosis:`The strongest current signal is a ${type.toLowerCase()} at ${stage.name.toLowerCase()}. ${top.status.desc}`,metric:stage.metric,evidenceTarget,actions,stages:session.answers.map((a,i)=>({name:leakStages[i].name,status:leakStatus.find(x=>x.id===a.status).label,impact:impacts.find(x=>x.id===a.impact).label,id:a.status})),createdAt:new Date().toISOString()};
  state.results.leak=result;delete state.drafts.leak;saveState();track('Tool Completed',{tool:'leak',stage:stage.id,type:top.status.id});session={};render();
}
function leakResult(){
  const r=state.results.leak;if(!r)return leakIntro();
  const copy=`GTM LEAK DIAGNOSIS\n\nFocus: ${r.type} at ${r.stage}\nConfidence: ${r.confidence}\n\nDiagnosis\n${r.diagnosis}\n\nMetric\n${r.metric}\n\nEvidence target\n${r.evidenceTarget}\n\nCandidate first moves\n${r.actions.map((x,i)=>`${i+1}. ${x}`).join('\n')}`;
  const rows=r.stages.map(s=>{const cls=s.id==='conversion'?'high':s.id==='volume'?'mixed':s.id==='unknown'?'unknown':'good';return `<div class="stage-row"><strong>${esc(s.name)}</strong><span>${esc(s.impact)}</span><span class="level ${cls}">${esc(s.status)}</span></div>`;}).join('');
  const content=`<div class="results"><div class="result-head"><span class="eyebrow">GTM leak diagnosis</span><h2>${esc(r.type)} at ${esc(r.stage)}.</h2><p>${esc(r.diagnosis)}</p><span class="confidence ${r.confidence}">● ${r.confidence==='strong'?'Strong':r.confidence==='medium'?'Working':'Low'} confidence</span></div><div class="result-grid"><article class="result-card focus"><span class="section-label">Focus stage</span><h2>${esc(r.stage)}</h2><span class="level ${r.status==='conversion'?'high':r.status==='volume'?'mixed':r.status==='unknown'?'unknown':'good'}">${esc(r.type)}</span><p>${esc(r.diagnosis)}</p></article><article class="result-card"><span class="section-label">Primary measure</span><h3>${esc(r.metric)}</h3><p>Record the current baseline before changing activity, messaging or process.</p></article><article class="result-card full"><span class="section-label">Across the journey</span><h3>Failure type and commercial importance</h3><div class="stage-list">${rows}</div></article><article class="result-card"><span class="section-label">Evidence target</span><h3>What to learn next</h3><div class="copy-box">${esc(r.evidenceTarget)}</div></article><article class="result-card"><span class="section-label">Candidate first moves</span><h3>Take these into the weekly planner</h3>${actionItems(r.actions)}</article><article class="result-card warning full"><span class="section-label">What this does not prove</span><h3>The most visible leak may have an upstream cause</h3><p>For example, weak sales conversion can begin with the wrong segment or unclear positioning. Use the recommended metric and customer evidence to confirm the cause before rebuilding the whole journey.</p></article></div>${resultActions(copy,'leak')}${nextCard('Choose the single constraint for this week','The Weekly Focus Planner will compare this diagnosis with the other completed tools, then generate one evidence target and three time-boxed actions.','/resources/weekly-focus','Build the weekly plan','leak')}</div>`;
  return layout(content,TOOL_META.leak.title,TOOL_META.leak.desc);
}


// 5. Weekly focus planner
const weeklyCriteria=[
  {id:'impact',title:'Commercial impact',q:'How much could progress on each constraint affect revenue, retention, speed or risk?',weight:1.35,labels:['High impact','Moderate impact','Lower impact']},
  {id:'evidence',title:'Evidence strength',q:'How strongly is each constraint supported by recent data or behaviour?',weight:1,labels:['Strong evidence','Some evidence','Mostly assumption']},
  {id:'control',title:'Influence this week',q:'How much meaningful progress can the team make within one week?',weight:1.2,labels:['Directly controllable','Partly controllable','Hard to influence']},
  {id:'urgency',title:'Urgency',q:'How costly is it to leave this unchanged for another week?',weight:.8,labels:['Urgent now','Important','Can wait']}
];
function candidateFromResults(){
  const out=[];
  if(state.results.bottleneck){const r=state.results.bottleneck;out.push({id:'bottleneck',source:'Growth dependency',name:r.label,evidenceTarget:r.evidenceTarget,actions:r.actions});}
  if(state.results.customer){const r=state.results.customer;out.push({id:'customer',source:'Customer focus',name:`Validate ${r.winner} as the priority segment`,evidenceTarget:r.evidenceTarget,actions:r.actions});}
  if(state.results.positioning){const r=state.results.positioning;out.push({id:'positioning',source:'Positioning',name:'Validate the working positioning direction',evidenceTarget:r.evidenceTarget,actions:r.actions});}
  if(state.results.leak){const r=state.results.leak;out.push({id:'leak',source:'GTM leak',name:`${r.type} at ${r.stage}`,evidenceTarget:r.evidenceTarget,actions:r.actions});}
  return out;
}
function weeklyIntro(){
  const count=candidateFromResults().length;
  return introPage('weekly',{label:'Weekly constraint planner',title:TOOL_META.weekly.title,lead:count?`You have ${count} completed diagnoses ready to compare. Choose one constraint, one evidence target and no more than three actions.`:'Complete another tool first, or add two competing priorities manually.',startFn:'startWeekly',startLabel:completed('weekly')?'Review or rebuild':'Build my weekly focus',meta:'About 5 minutes · Imports previous results · One constraint and three actions',benefits:[['Compare, do not combine','A good week has one commercial learning priority.'],['Use existing diagnoses','Results from the other tools appear automatically.'],['End with evidence','Friday success is defined by what was learned or changed.']]});
}
window.startWeekly=function(){
  const imported=candidateFromResults();const d=state.drafts.weekly||{};session={tool:'weekly',step:d.step||0,candidates:d.candidates||imported,selected:d.selected||imported.slice(0,3).map(x=>x.id),ratings:d.ratings||weeklyCriteria.map(()=>({})),hours:d.hours||4};track('Tool Started',{tool:'weekly',imported:imported.length});renderWeekly();
};
function persistWeekly(){state.drafts.weekly={step:session.step,candidates:session.candidates,selected:session.selected,ratings:session.ratings,hours:session.hours};saveState();}
window.toggleCandidate=function(id){if(session.selected.includes(id))session.selected=session.selected.filter(x=>x!==id);else if(session.selected.length<3)session.selected.push(id);persistWeekly();renderWeekly();};
window.addManualCandidate=function(){const input=document.getElementById('manualCandidate'),name=clean(input?.value);if(name.split(' ').length<3)return;const id='manual-'+uid();session.candidates.push({id,source:'Manual priority',name,evidenceTarget:`Collect evidence that confirms whether ${name.toLowerCase()} is the current commercial constraint.`,actions:[`Define the current baseline and the specific evidence that would change the decision.`,`Run one customer-facing or operational test related to ${name.toLowerCase()}.`,`Review the result on Friday and decide whether to continue, change or stop.`]});session.selected.push(id);persistWeekly();renderWeekly();};
function selectedCandidates(){return session.candidates.filter(c=>session.selected.includes(c.id));}
window.weeklyCandidatesNext=function(){if(selectedCandidates().length<2)return;session.step=1;persistWeekly();renderWeekly();window.scrollTo(0,0);};
window.chooseWeeklyRating=function(candidateId,value){const ci=session.step-1;session.ratings[ci][candidateId]=value;persistWeekly();renderWeekly();};
window.weeklyNext=function(){const ci=session.step-1,cands=selectedCandidates();if(cands.some(c=>session.ratings[ci][c.id]===undefined))return;if(session.step<weeklyCriteria.length){session.step++;persistWeekly();renderWeekly();window.scrollTo(0,0);}else{session.step=weeklyCriteria.length+1;persistWeekly();renderWeekly();}};
window.setHours=function(h){session.hours=h;persistWeekly();renderWeekly();};
window.finishWeekly=function(){
  const cands=selectedCandidates();const totals=cands.map(c=>({c,score:weeklyCriteria.reduce((sum,cr,ci)=>sum+(session.ratings[ci][c.id]||1)*cr.weight,0)})).sort((a,b)=>b.score-a.score);const top=totals[0],second=totals[1];const gap=top.score-second.score;const conf=gap>=1.6?'strong':gap>=.7?'medium':'low';
  const durations=session.hours<=2?['30 minutes','60 minutes','30 minutes']:session.hours<=4?['60 minutes','2 hours','60 minutes']:['90 minutes','4 hours','2.5 hours'];
  const actions=top.c.actions.slice(0,3).map((x,i)=>({text:x,time:durations[i]}));
  const result={name:top.c.name,source:top.c.source,confidence:conf,evidenceTarget:top.c.evidenceTarget,actions,defer:totals.slice(1).map(x=>x.c.name),hours:session.hours,review:['Did we reach the evidence target?','What changed our understanding of the customer or constraint?','Should we continue, change or stop this work next week?'],createdAt:new Date().toISOString()};
  state.results.weekly=result;delete state.drafts.weekly;saveState();track('Tool Completed',{tool:'weekly',source:top.c.source});session={};render();
};
window.weeklyBack=function(){if(session.step===0){session={};render();}else{session.step--;persistWeekly();renderWeekly();window.scrollTo(0,0);}};
function renderWeekly(){
  if(session.step===0){
    const cards=session.candidates.map(c=>`<button class="option ${session.selected.includes(c.id)?'selected':''}" onclick="toggleCandidate('${c.id}')"><span class="option-mark">${session.selected.includes(c.id)?'✓':'+'}</span><span><strong>${esc(c.name)}</strong><span class="desc">${esc(c.source)}</span></span></button>`).join('');
    app.innerHTML=layout(`<div class="wizard">${progress(0,weeklyCriteria.length+2,'Choose the competing constraints')}<section class="panel"><span class="step-kicker">Candidate constraints</span><h2>Which two or three priorities are competing for attention?</h2><p class="intro">Completed tool results are imported automatically. Select at least two and no more than three.</p><div class="options">${cards||'<div class="empty">No completed diagnoses yet. Add two manual priorities below.</div>'}</div><div class="field"><label>Add a manual priority</label><div style="display:flex;gap:8px"><input id="manualCandidate" placeholder="e.g. Improve onboarding activation for new accounts"><button class="btn secondary" onclick="addManualCandidate()">Add</button></div><div class="hint">Use a specific problem, not a broad task such as “do marketing”.</div></div><div class="quality ${selectedCandidates().length>=2?'good':'warn'}">${selectedCandidates().length} selected. Choose 2 or 3.</div><div class="wizard-actions"><button class="back" onclick="weeklyBack()">← Start</button><button class="btn primary" onclick="weeklyCandidatesNext()" ${selectedCandidates().length>=2?'':'disabled'}>Compare priorities →</button></div></section></div>`,TOOL_META.weekly.title,TOOL_META.weekly.desc);return;
  }
  if(session.step<=weeklyCriteria.length){
    const ci=session.step-1,c=weeklyCriteria[ci],cands=selectedCandidates();const complete=cands.every(x=>session.ratings[ci][x.id]!==undefined);
    const rows=cands.map(x=>`<div class="segment-row"><strong>${esc(x.name)}</strong><div class="rating-buttons" style="grid-template-columns:repeat(3,1fr)">${c.labels.map((label,i)=>{const value=3-i;return `<button class="rating ${session.ratings[ci][x.id]===value?'selected':''}" onclick="chooseWeeklyRating('${x.id}',${value})">${esc(label)}</button>`;}).join('')}</div></div>`).join('');
    app.innerHTML=layout(`<div class="wizard">${progress(session.step,weeklyCriteria.length+2,c.title)}<section class="panel"><span class="step-kicker">${esc(c.title)}</span><h2>${esc(c.q)}</h2><div class="segment-list">${rows}</div><div class="wizard-actions"><button class="back" onclick="weeklyBack()">← Back</button><button class="btn primary" onclick="weeklyNext()" ${complete?'':'disabled'}>Continue →</button></div></section></div>`,TOOL_META.weekly.title,TOOL_META.weekly.desc);return;
  }
  app.innerHTML=layout(`<div class="wizard">${progress(weeklyCriteria.length+1,weeklyCriteria.length+2,'Set the capacity')}<section class="panel"><span class="step-kicker">Available capacity</span><h2>How much focused time can the team protect this week?</h2><p class="intro">This controls the size of the three actions. Choose a realistic amount, not the theoretical maximum.</p><div class="options">${[[2,'2 focused hours','A small evidence sprint'],[4,'4 focused hours','A meaningful test and review'],[8,'8 or more hours','A deeper customer-facing or operational experiment']].map((x,i)=>`<button type="button" class="option ${session.hours===x[0]?'selected':''}" onclick="setHours(${x[0]})"><span class="option-mark">${String.fromCharCode(65+i)}</span><span><strong>${esc(x[1])}</strong><span class="desc">${esc(x[2])}</span></span></button>`).join('')}</div><div class="wizard-actions"><button class="back" onclick="weeklyBack()">← Back</button><button class="btn primary" onclick="finishWeekly()">Build my week →</button></div></section></div>`,TOOL_META.weekly.title,TOOL_META.weekly.desc);
}
function weeklyResult(){
  const r=state.results.weekly;if(!r)return weeklyIntro();
  const copy=`WEEKLY GROWTH FOCUS\n\nConstraint: ${r.name}\nSource: ${r.source}\nConfidence: ${r.confidence}\nAvailable capacity: ${r.hours}+ focused hours\n\nEvidence target\n${r.evidenceTarget}\n\nThree actions\n${r.actions.map((x,i)=>`${i+1}. ${x.text} (${x.time})`).join('\n')}\n\nDefer\n${r.defer.map(x=>`- ${x}`).join('\n')}\n\nFriday review\n${r.review.map((x,i)=>`${i+1}. ${x}`).join('\n')}`;
  const content=`<div class="results"><div class="result-head"><span class="eyebrow">Your weekly growth focus</span><h2>${esc(r.name)}</h2><p>Protect the week around one constraint. Everything else remains visible, but deferred.</p><span class="confidence ${r.confidence}">● ${r.confidence==='strong'?'Strong':r.confidence==='medium'?'Working':'Low'} decision confidence</span></div><div class="result-grid"><article class="result-card focus full"><span class="section-label">The constraint</span><h2>${esc(r.name)}</h2><div class="tool-meta"><span class="chip">Source: ${esc(r.source)}</span><span class="chip">Capacity: ${r.hours}+ focused hours</span></div></article><article class="result-card full"><span class="section-label">Evidence target</span><h3>By Friday, we need to know or change this</h3><div class="copy-box">${esc(r.evidenceTarget)}</div></article><article class="result-card full"><span class="section-label">Three actions</span><h3>The whole week</h3><div class="action-list">${r.actions.map((x,i)=>`<div class="action-item"><b>${i+1}</b><p><strong>${esc(x.time)}:</strong> ${esc(x.text)}</p></div>`).join('')}</div></article><article class="result-card"><span class="section-label">Explicit defer list</span><h3>Not this week</h3><div class="defer-list">${r.defer.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>No other priorities recorded</span>'}</div></article><article class="result-card"><span class="section-label">Friday review</span><h3>Close the learning loop</h3>${evidenceItems(r.review)}</article><article class="result-card warning full"><span class="section-label">Working rule</span><h3>Do not add a fourth action</h3><p>When new work appears, either defer it or replace one of the three actions. A focused week is valuable because it creates interpretable evidence.</p></article></div>${resultActions(copy,'weekly')}<div class="next-card"><div><h3>Need a second pair of eyes?</h3><p>Bring the diagnosis, evidence target and current numbers to a focused WSS Growth Audit.</p></div><a class="btn" href="/book" data-track="Growth Audit Clicked" data-tool="weekly">Bring this to a Growth Audit →</a></div></div>`;
  return layout(content,TOOL_META.weekly.title,TOOL_META.weekly.desc);
}

function render(){
  const path=currentPath();
  if(path==='/resources/growth-dependency'){app.innerHTML=bottleneckResult();return;}
  if(path==='/resources/customer-segment'){app.innerHTML=customerResult();return;}
  if(path==='/resources/positioning'){app.innerHTML=positioningResult();return;}
  if(path==='/resources/gtm-leak'){app.innerHTML=leakResult();return;}
  if(path==='/resources/weekly-focus'){app.innerHTML=weeklyResult();return;}
  app.innerHTML=bottleneckResult();
}

// Expose selected helpers used by inline event handlers.
Object.assign(window,{state,copyText,restartTool,track,renderPositioning,renderPositionReview,renderWeekly});
render();
track('Tool Viewed',{tool:currentTool(),source:'resources'});
